  'Private key: saved ✓': ['Klucz prywatny: zapisany ✓', 'Privater Schlüssel: gespeichert ✓', 'Clé privée : enregistrée ✓', 'Clave privada: guardada ✓', 'Chiave privata: salvata ✓', 'Приватний ключ: збережено ✓'],
